export interface Opportunity {
  id: number;
  ticker: string;
  name: string;
  category: string;
  score: number;
  potentialReturn: number;
  dividendYield: number;
  riskLevel: OpportunityRiskLevel;
  reason: string;
  positives: string[];
  risks: string[];
  /** @nullable */
  sector?: string | null;
  /**
     * Diferença em p.p. entre o DY do ativo e a mediana do setor
     * @nullable
     */
  dividendPremiumPP?: number | null;
  /** @nullable */
  sectorMedianYield?: number | null;
  /** @nullable */
  sectorSampleSize?: number | null;
  /** DY acima do dobro da mediana setorial — faixa que costuma indicar amortização de cota, evento não recorrente ou preço em colapso */
  implausibleYield?: boolean;
  /** @nullable */
  dividendSustainability?: string | null;
  horizon: string;
  /** @nullable */
  currentPrice?: number | null;
  /**
     * Preenchido só quando currentPrice é o último preço conhecido em vez da cotação de agora (provedor indisponível) — é a data dessa última cotação. Null quando o preço é ao vivo. Mesmo campo e mesma semântica de Asset.priceAsOf.
     * @nullable
     */
  priceAsOf?: string | null;
  /**
     * Periodicidade real de pagamento de proventos nos últimos 12 meses, a partir do histórico real. Null se o ativo não pagou nada no período.
     * @nullable
     */
  dividendFrequency?: OpportunityDividendFrequency;
}

export interface OpportunityList {
  /** true quando o perfil pede ordenação por prêmio de dividendo mas a lista ainda não tem referência setorial — acontece com linhas gravadas antes da varredura que passou a persistir o setor. Some na próxima atualização. */
  dividendPremiumPending?: boolean;
  /** Critério que ordenou a lista. premio_dividendo quando o perfil declara objetivo de renda; perfil_de_risco quando há perfil com outro objetivo; score quando não há perfil definido. */
  orderedBy: OpportunityListOrderedBy;
  items: Opportunity[];
}

