/**
 * De onde vem a política em uso. "personalizado" = salva pelo usuário; "perfil" = padrão derivado do perfil de investidor; "generico" = padrão usado por falta de perfil preenchido, não calculado a partir das respostas.
 */
export type AllocationOverviewSource = typeof AllocationOverviewSource[keyof typeof AllocationOverviewSource];


export const AllocationOverviewSource = {
  personalizado: 'personalizado',
  perfil: 'perfil',
  generico: 'generico',
} as const;

export interface AllocationOverview {
  /** De onde vem a política em uso. "personalizado" = salva pelo usuário; "perfil" = padrão derivado do perfil de investidor; "generico" = padrão usado por falta de perfil preenchido, não calculado a partir das respostas. */
  source: AllocationOverviewSource;
  totalPatrimony: number;
  items: AllocationItem[];
}

/**
 * Quanto comprar, em quantidade, se a fatia inteira da classe for para este ativo. Nunca arredonda para cima: sugerir quantidade que custa mais que a fatia seria mandar gastar dinheiro que o usuário não disse que tem.
 */
export interface PurchaseSizing {
  /** Cotação usada na conta, para o usuário conferir. */
  unitPrice: number;
  /** Unidades inteiras em bolsa (mercado fracionário negocia a partir de 1); múltiplos de 0,01 título no Tesouro Direto. Zero é resposta válida — a fatia não alcança uma unidade, ou não atinge o piso de R$ 30 do Tesouro. */
  units: number;
  investedAmount: number;
  /** O que sobra da fatia. Sem isso a soma não fecha na tela. */
  leftover: number;
}

export interface AllocationPlanSuggestion {
  ticker: string;
  name: string;
  score: number;
  reason: string;
  /** Null quando não há cotação real para o ticker. Estimar preço para poder mostrar quantidade seria inventar o número mais fácil de conferir na tela. */
  sizing?: PurchaseSizing | null;
}

export interface TreasuryPriceOnDate {
  /** Data-base efetivamente usada. Pode ser anterior à pedida — compra em fim de semana ou feriado não tem publicação no próprio dia, e a tela precisa dizer de quando é o número. */
  baseDate: string;
  buyUnitPrice: number;
}

export interface TreasuryBondOption {
  bondType: string;
  maturityDate: string;
  baseDate: string;
  buyRate: number;
  buyUnitPrice: number;
  /**
     * PU de recompra — é este lado que marca uma posição já detida. Null quando o arquivo não trouxe: a posição fica no preço médio em vez de ser marcada pelo preço de compra, que a superestimaria.
     * @nullable
     */
  sellUnitPrice?: number | null;
  /** Rótulo canônico usado como ticker da posição, ex. "TESOURO IPCA+ 2035". */
  label: string;
}

export interface TreasurySuggestion {
  bondType: string;
  maturityDate: string;
  /** Data-base da taxa. O Tesouro publica o arquivo com um ou dois dias úteis de atraso, então a taxa nunca é "de agora" — exibir a data junto. */
  baseDate: string;
  /** Taxa já rotulada conforme a família ("IPCA + 8,04% a.a.", "14,11% a.a.", "Selic + 0,04%"). O número cru significa coisas diferentes em cada uma — no Tesouro Selic é ágio/deságio sobre a Selic, não o rendimento. */
  rateLabel: string;
  /** Preço do título inteiro. */
  unitPrice: number;
  /** Compra mínima — 1% do título, com piso de R$ 30 do Tesouro Direto. */
  minimumInvestment: number;
  reason: string;
  /** Fração do título que a fatia de renda fixa compra, em múltiplos de 0,01. */
  sizing?: PurchaseSizing | null;
}

/**
 * Por que a lista de sugestões está vazia, quando está. "sem_ticker_de_bolsa" = renda fixa e fundos, que não são ranqueáveis por ticker. "sem_candidato" = classe negociada em bolsa que não tem nenhum ativo aprovado na varredura — hoje é o caso dos ETFs, que não têm fundamento individual (P/L, ROE, margem) e por isso não passam pela triagem por fundamentos. "tesouro_indisponivel" = renda fixa cuja sincronização com o Tesouro Direto ainda não rodou ou falhou; `sem_ticker_de_bolsa` segue valendo para fundos, que não têm fonte nenhuma.
 */
export type AllocationPlanItemSuggestionsStatus = typeof AllocationPlanItemSuggestionsStatus[keyof typeof AllocationPlanItemSuggestionsStatus];


export const AllocationPlanItemSuggestionsStatus = {
  ok: 'ok',
  sem_ticker_de_bolsa: 'sem_ticker_de_bolsa',
  sem_candidato: 'sem_candidato',
  tesouro_indisponivel: 'tesouro_indisponivel',
} as const;

export interface AllocationPlanItem {
  category: string;
  amount: number;
  /** Fatia deste aporte, não o alvo da classe na carteira. */
  sharePercent: number;
  /** Por que a lista de sugestões está vazia, quando está. "sem_ticker_de_bolsa" = renda fixa e fundos, que não são ranqueáveis por ticker. "sem_candidato" = classe negociada em bolsa que não tem nenhum ativo aprovado na varredura — hoje é o caso dos ETFs, que não têm fundamento individual (P/L, ROE, margem) e por isso não passam pela triagem por fundamentos. "tesouro_indisponivel" = renda fixa cuja sincronização com o Tesouro Direto ainda não rodou ou falhou; `sem_ticker_de_bolsa` segue valendo para fundos, que não têm fonte nenhuma. */
  suggestionsStatus: AllocationPlanItemSuggestionsStatus;
  /** Ativos da classe, na mesma ordem da tela de Oportunidades. */
  suggestions: AllocationPlanSuggestion[];
  /** Títulos do Tesouro Direto sugeridos para a fatia de renda fixa. Lista separada de `suggestions` de propósito: título público não tem ticker nem score do Radar, e encaixá-lo naquele formato exigiria inventar os dois. */
  treasurySuggestions?: TreasurySuggestion[];
}

export type AllocationPlanSource = typeof AllocationPlanSource[keyof typeof AllocationPlanSource];


export const AllocationPlanSource = {
  personalizado: 'personalizado',
  perfil: 'perfil',
  generico: 'generico',
} as const;

export interface AllocationPlan {
  amount: number;
  source: AllocationPlanSource;
  /** Critério de ordenação das sugestões, o mesmo de /opportunities. */
  orderedBy: string;
  items: AllocationPlanItem[];
  /** Soma dos desvios absolutos (pp) antes do aporte. */
  deviationBefore?: number;
  /** Soma dos desvios absolutos (pp) depois do aporte sugerido. */
  deviationAfter?: number;
}

export interface IncomeGoalInput {
  /** @minimum 1 */
  targetMonthlyIncome: number;
  /**
     * @minimum 2020
     * @maximum 2100
     */
  targetYear: number;
}

/**
 * requiredMonthlyContribution não considera reinvestimento dos proventos, o que o torna conservador por construção — o percurso real tende a ser mais curto.
 */
export interface IncomeGoalProgress {
  targetYear: number;
  targetMonthlyIncome: number;
  currentMonthlyIncome: number;
  progressPercent: number;
  monthsRemaining: number;
  achieved: boolean;
  overdue: boolean;
  /** @nullable */
  requiredCapital?: number | null;
  /** @nullable */
  capitalGap?: number | null;
  /** @nullable */
  requiredMonthlyContribution?: number | null;
}

export interface PortfolioReport {
  generatedAt: string;
  summary: PortfolioSummary;
  analyses: AssetAnalysis[];
  topAlerts: Alert[];
  opportunities: Opportunity[];
}

export type ValidateTickerParams = {
ticker: string;
};

export type GetTreasuryPriceOnDateParams = {
bondType: string;
/**
 * @pattern ^\d{4}-\d{2}-\d{2}$
 */
maturityDate: string;
/**
 * @pattern ^\d{4}-\d{2}-\d{2}$
 */
date: string;
};

export type GetAllocationPlanParams = {
/**
 * @minimum 0.01
 */
amount: number;
};

